# Check for corrupted files
from PIL import Image
import numpy as np

def find_corrupted_files(directory):
    corrupted = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            try:
                with Image.open(filepath) as img:
                    img.verify()
                # Reopen to check loading (verify doesn't close properly)
                with Image.open(filepath) as img:
                    img.load()
            except Exception as e:
                corrupted.append((filepath, str(e)))
    return corrupted

corrupted = find_corrupted_files(train_dir)
print(f"Found {len(corrupted)} corrupted files:")
for f, err in corrupted:
    print(f"  {f}: {err}")"}

